			target: "ls",
			decision: "allow",
		},
		plan_updated: { type: "plan_updated", steps: [{ title: "read" }] },
		reasoning_delta: { type: "reasoning_delta", delta: "hmm" },
		harness_log: { type: "harness_log", text: "[PROBE] hello" },
