		streamer.handleEvent(MINIMAL_EVENT.tool_updated);
		const emitted = streamer.handleEvent(MINIMAL_EVENT.tool_finished);
		const result = emitted.find((e) => e.text.startsWith("[RESULT]"));
		expect(result).toBeDefined();
