  } = ctx;
  switch (type) {
    case 'MSG_START':
      handlers.handleMsgStart(payload);
      break;
    case 'MSG_UPDATE':
      handlers.handleMsgUpdate(payload);
      break;
    case 'TOOL_START':
      handlers.handleToolStart(payload);
      break;
    case 'TOOL_UPDATE':
      handlers.handleToolUpdate(payload);
      break;
    case 'TOOL_END':
      handlers.handleToolEnd(payload);
      break;
    case 'AGENT_DONE':
      handlers.handleAgentDone();
      break;
    case 'STREAMING_UPDATE':
      setIsAgentRunning(payload.isStreaming);
      break;
    case 'ENGINE_STATE':
      setEngineState(payload);
      if (payload.status === 'running') {
        setIsAgentRunning(true);
      } else if (
        payload.status === 'idle' ||
        payload.status === 'checkpoint' ||
        payload.status === 'paused'
      ) {
        setIsAgentRunning(false);
      }
      break;
    case 'PROCESS_START':
      if (payload.stageType === 'agent' || (!payload.command && payload.prompt)) {
        addProcessLog(
          '[AGENT]',
          `Agent reasoning started in stage: ${payload.stageName || payload.stageId || ''}`,
          payload,
        );
      } else {
        addProcessLog('[CI/CMD]', `Starting CI command: ${payload.command || ''}`, payload);
      }
      setIsAgentRunning(true);
      break;
    case 'PROCESS_STDOUT': {
      const defaultTag =
        payload.tag || (payload.stageType === 'agent' ? '[AGENT]' : '[CI/CMD]');
      // The backend mirrors tool invocations globally as "[SYSTEM] Tool
      // invocation: <name> with arguments: <args>" system logs
      // (api/eventBridge.js). Re-tag them as compact, TOOL-chip-filterable
      // [TOOL] lines so tool activity is observable in every project scope
      // (TOOL_START events only reach the session's own subscribers).
      if (typeof payload.chunk === 'string') {
        const invocation = parseSystemToolInvocation(payload.chunk);
        if (invocation) {
          addProcessLog(
            '[TOOL]',
            `⚡ ${invocation.name}(${compactArgsForLog(invocation.args, 120, invocation.name)})`,
            payload,
          );
          break;
        }
      }
      addProcessLog(defaultTag, payload.chunk || '', payload);
      break;
    }
    case 'PROCESS_STDERR':
      addProcessLog('[ERROR]', payload.chunk || '', payload);
      break;
    case 'PROCESS_LOG_ENTRIES': {
      // Structured runner log batches: first-class entries (tool calls,
      // results, thinking, errors, telemetry) appended live. Older clients
      // without the appender ignore the frame; history arrives via refetch.
      if (typeof addProcessLogEntries === 'function') {
        addProcessLogEntries(payload.entries, payload);
        if (Array.isArray(payload.entries) && payload.entries.length > 0) {
          setIsAgentRunning(true);
        }
      }
      break;
    }
    case 'PROCESS_EXIT':
      addProcessLog(
        payload.exitCode === 0 ? '[CI/CMD]' : '[ERROR]',
        `Process exited with code ${payload.exitCode}`,
        payload,
      );
      setIsAgentRunning(false);
      if (payload.exitCode === 0) {
        onNotificationRef.current?.({
          type: 'success',
          title: 'CI Passed',
          message: `CI command passed (exit 0)${payload.command ? `: ${payload.command}` : ''}`,
        });
      } else {
        onNotificationRef.current?.({
          type: 'error',
          title: 'CI Failed',
          message: `CI command exited with code ${payload.exitCode}${payload.command ? ` (${payload.command})` : ''}`,
        });
      }
      break;
    case 'STAGE_ENTER':
      addProcessLog(
        '[INFO]',
        `Entering stage: ${payload.stageName || payload.stageId || ''} (${payload.stageType || 'agent'})`,
        payload,
      );
      break;
    case 'STAGE_CHECKPOINT_WAIT':
      addProcessLog(
        '[HUMAN]',
        `Checkpoint: ${payload.message || 'Waiting for human approval'}`,
        payload,
      );
      setIsAgentRunning(false);
      onNotificationRef.current?.({
        type: 'info',
        title: 'Review Required',
        message: payload.message || 'Human review checkpoint reached',
      });
      break;
    case 'STAGE_COMPLETE': {
      const stageName = payload.stageName || payload.stageId || 'Stage';
      const nextStageName = payload.nextStageName;
      const logMsg =
        payload.message ||
        (nextStageName
          ? `Stage '${stageName}' complete — advancing to '${nextStageName}'`
          : payload.isTerminal || payload.pipelineFinished
            ? `Stage '${stageName}' complete — pipeline finished`
            : `Stage '${stageName}' complete`);
      addProcessLog('[AGENT]', logMsg, payload);
      break;
    }
    case 'STAGE_FAILBACK':
      addProcessLog(
        '[ERROR]',
        `Stage failback triggered -> target stage: ${payload.targetStageId || 'previous'}${payload.error ? ` (${payload.error})` : ''}`,
        payload,
      );
      onNotificationRef.current?.({
        type: 'error',
        title: 'Stage Failed',
        message: payload.error
          ? `${payload.error}`
          : `Failback to stage: ${payload.targetStageId || 'previous'}`,
      });
      break;
    case 'NOTIFICATION':
      if (payload) {
        onNotificationRef.current?.({
          type: payload.type || 'info',
          title: payload.title || 'Notification',
          message: payload.message || '',
          duration: payload.duration || (payload.type === 'error' ? 8000 : 5000),
        });
      }
      break;
    // Live board sync: a task's board position or status changed elsewhere
    // (drag in another tab, agent stage advance, create, update). Push the
    // change into the task list without requiring a page refresh.
    case 'TASK_UPDATED':
      onTaskUpdatedRef.current?.(payload);
      break;
    case 'TASK_DELETED':
      onTaskDeletedRef.current?.(payload);
      break;
    // PR review: a comment was created/updated/replied/deleted (or a
    // snapshot commit landed) — let the open review view merge it live.
    case 'REVIEW_UPDATED':
      onReviewUpdatedRef.current?.(payload);
      break;
    // Chat progress: a streaming tail for one in-flight chat turn — the
    // ChatTurnProvider matches it to its turn by turnId (optional ref: old
    // callers without chat wiring simply ignore the frame).
    case 'CHAT_PROGRESS':
      onChatProgressRef?.current?.(payload);
      break;
    // App link: the project's "Go to App" record changed (script PATCH,
    // agent skill, or health probe) — merge it so the link appears live.
    // Optional ref: old callers without project wiring ignore the frame.
    case 'APP_STATUS_UPDATED':
      onProjectUpdatedRef?.current?.(payload);
      break;
    case 'CONNECTED':
      // Server-side acknowledgement that the WS connection for this
      // project is established.
      break;
    default:
      logger.warn('Unknown WS event:', type, payload);
  }
}

./api/flow/execution/applyRunnerReport.js
---
import { generateStageReportContent } from "../../watch/index.js";
import { redactSecretsText } from "../../../shared/redactSecrets.js";
import { recordReliabilitySample } from "../../watch/reliabilityShared.js";
import { stageWantsReport } from "../../promptCuration.js";
import { stageElapsedSeconds } from "../stagePolicy.js";
import { resolveStagesForTask } from "../stageResolution.js";
import { normalizeStageType } from "../../projectStore.js";
import { routeStageError } from "./routeStageError.js";
import { parkTaskForSurvey } from "./parkTaskForSurvey.js";

/***
 * MARK: applyRunnerReport
 * @description Engine-owned finish for a Runner-reported stage (remote
 *   dispatch integration, ADR 0009 step 6). The Runner owns git
 *   (clone/worktree/commit/push — transport row 1/2, D2: the backend never
 *   touches remotes for Runner work); the backend owns everything else,
 *   composing the SAME standalone transitions as the embedded path:
 *   formal report save (opt-in stages), reliability sample, question-me
 *   survey park (shared with executeStage — a remote run can never skip
 *   the human survey), failure routing via routeStageError, and
 *   advanceStage plus the scheduler follow-on kick. Call only after the
 *   lease fence accepted the execution (complete-execution does that).
 * @example await applyRunnerReport({ store, projectStore, projectId: 'p', taskId: 't', outcome: { status: 'passed', output: '...' } }) => { advanced: true, ... }
 * @param {Object} args - Context.
 * @param {Object} args.store - Task store.
 * @param {Object} args.projectStore - Project store.
 * @param {string} args.projectId - Project id.
 * @param {string} args.taskId - Task id.
 * @param {Object} args.outcome - Runner outcome.
 * @param {string} args.outcome.status - `passed` or `failed`.
 * @param {string} [args.outcome.output] - Final assistant text.
 * @param {string} [args.outcome.summary] - Run summary.
 * @param {Array} [args.outcome.modifiedFiles] - Modified files.
 * @param {string} [args.outcome.harnessId] - Harness that ran.
 * @param {string} [args.outcome.failureKind] - Failure taxonomy kind.
 * @param {string} [args.outcome.failureReason] - Failure message.
 * @param {string} [args.outcome.duration] - Run duration seconds.
 * @param {string} [args.outcome.runnerId] - Reporting Runner.
 * @returns {Promise<Object>} `{ advanced, status, ... }`.
 ***/
export async function applyRunnerReport({
	store,
	projectStore,
	projectId,
	taskId,
	outcome,
}) {
	const task = store.getTask(projectId, taskId);
	if (!task) {
		const err = new Error(`Task ${taskId} not found`);
		err.statusCode = 404;
		err.code = "TASK_NOT_FOUND";
		throw err;
	}
	const project = projectStore?.getProject?.(projectId);
	// The runner's completion payload (final assistant text, summaries) is
	// committed to the repository via stage reports and task markdown — the
	// same guarantee as the live log path: redact before persistence.
	// Structured log entries ingested live are already redacted at creation.
	const redactedOutput = redactSecretsText(outcome.output || "");
	const redactedSummary = redactSecretsText(outcome.summary || "");
	const stages = resolveStagesForTask(project, task);
	const stage =
		stages.find(
			(s) =>
				String(s.id) === String(task.currentStageId) ||
				(s.name &&
					String(s.name).toLowerCase() ===
						String(task.currentStageId).toLowerCase()),
		) ||
		stages[0] || { id: "stage", name: "Stage", type: "agent" };
	const stageType = normalizeStageType(stage.type);
	const bridge = store.eventBridge;
	const cwd = project?.cwd;
	const via = outcome.runnerId ? `via Runner ${outcome.runnerId}` : "via Runner";
	const duration = outcome.duration || "0.0";

	if (outcome.status === "failed") {
		const err = new Error(outcome.failureReason || "Stage failed on the Runner");
		// The runner's completion payload carries the tail of the run output
		// (runner/daemon.js caps it). Keep it on the error so the failure
		// report renders the actual failing output instead of only the
		// reason — thin "exit code 1" reports hid every branch result
		// (task b5716327). handleStageFailure already renders error.stdout
		// into the report, lastError, and timeline excerpt.
		if (redactedOutput) err.stdout = redactedOutput;
		return routeStageError(
			store,
			projectId,
			taskId,
			stage,
			err,
			{
				stages,
				bridge,
				projectCwd: cwd,
				runOutcome: {
					harnessId: outcome.harnessId,
					failureKind: outcome.failureKind,
				},
				classifyAs: {
					failureKind: outcome.failureKind,
					failureReason: outcome.failureReason,
				},
			},
		);
	}

	const at = Date.now();
	recordReliabilitySample(store, projectId, taskId, {
		harnessId: outcome.harnessId || "unknown",
		failureKind: "none",
		at,
		atRaw: new Date(at).toISOString(),
		stageId: stage.id,
	});
	bridge?.emitSystemLog?.(
		projectId,
		`[SYSTEM] Stage '${stage.name || stage.id}' completed in ${duration}s (${via})`,
		{ taskId, stageId: stage.id, duration },
	);

	if (stageWantsReport(stage)) {
		const reportContent = generateStageReportContent({
			task,
			stage,
			output: redactedOutput,
			summary: redactedSummary,
			modifiedFiles: outcome.modifiedFiles || [],
			status: "PASSED",
			duration,
		});
		store.saveStageReport(projectId, taskId, {
			stageName: stage.name || stage.id,
			stageId: stage.id,
			duration: stageElapsedSeconds(task),
			status: "PASSED",
			content: reportContent,
			projectCwd: cwd,
			harnessId: outcome.harnessId,
			failureKind: outcome.failureKind || "none",
		});
	}

	task.history.push({
		timestamp: new Date().toISOString(),
		action: `Agent stage completed: ${stage.name || stage.id} (${via})`,
	});
	store._saveTaskMarkdown(cwd, task);

	const surveyPark = parkTaskForSurvey({
		store,
		projectId,
		taskId,
		task,
		stage,
		projectObj: project,
		cwd,
		bridge,
		stageType,
		finalOutput: redactedOutput,
		streamedOutput: redactedOutput,
		summary: redactedSummary,
		modifiedFiles: outcome.modifiedFiles || [],
		duration,
		via,
	});
	if (surveyPark.parked) return { advanced: false, ...surveyPark.response };

	task.surveyPending = false;
	task.infraRetryCount = 0;
	store.advanceStage(projectId, taskId, stages, bridge, cwd);

	store.lastCompletedTask = { projectId, taskId, timestamp: Date.now() };
	if (store.schedulerRunning) {
		setTimeout(() => {
			store.scheduleTick().catch(() => {});
		}, 50);
	}

	return {
		advanced: true,
		task,
		stageType,
		status: "passed",
		output: redactedOutput,
		summary: redactedSummary,
		modifiedFiles: outcome.modifiedFiles || [],
		model: stage.model || null,
		duration,
	};
}

/**
 * MARK: logProcessor
 * @description THE single place that turns normalized agent events into
 *   canonical log records (`logRecord.js`). The agent log streamer
 *   (`agentLogStreamer.js`) is a thin stateful shell around this processor:
 *   it owns feed plumbing (consumeFeed/snapshot/render) while every
 *   event→record decision lives here, so harnesses and the UI can migrate
 *   independently once this seam and its contract test exist.
 *
 *   Responsibilities:
 *   - block state (text/thinking/tool) and `blockId` assignment;
 *   - telemetry/permission/plan/raw lanes for the unified vocabulary
 *     (`usage_updated`, `session_meta`, `permission_requested/resolved`,
 *     `plan_updated`, `reasoning_delta`, `harness_log`);
 *   - usage telemetry derived from `usage` payloads riding on
 *     `assistant_delta`/`run_finished` (pi message usage/stopReason, agy
 *     result usage) as well as explicit `usage_updated` events;
 *   - unknown-event capture into the bounded raw lane
 *     (`evidence.reason = "unmapped"`) instead of silent drops;
 *   - caps/eviction per lane and total (`logEntriesMaxCount`);
 *   - ANSI strip for `text` (preserved verbatim in `evidence.sourceEvent`).
 *
 *   Backwards compatibility: for the original 8 events the produced entries
 *   keep their exact kind/feed/text/meta — the new canonical fields (`seq`,
 *   `blockId`, `fidelity`, …) are purely additive.
 */

import {
	boundRawSource,
	FIDELITY_SYNTHESIZED,
	makeLogRecord,
	RECORD_LIMITS,
	stripAnsiText,
} from "./logRecord.js";
import {
	redactDeepStrings,
	redactSecretsText,
} from "../../../shared/redactSecrets.js";
import {
	summarizePermission,
	summarizePlan,
	summarizeRaw,
	summarizeToolResult,
	summarizeToolStart,
	summarizeUsage,
} from "../../../shared/toolLogFormat.js";

/***
 * MARK: DEFAULT_PROCESSOR_OPTIONS
 * @description Default options for `createLogProcessor`. Mirrors the
 *   streamer defaults (`maxEntryBytes` 0 = uncapped narrative text; task-log
 *   growth bounded by the structured-entry cap) plus the unified lane
 *   budgets (`telemetryMaxCount`, `rawMaxCount`, `rawMaxBytes`).
 ***/
export const DEFAULT_PROCESSOR_OPTIONS = Object.freeze({
	hideThinking: true,
	toolArgsMaxLength: 400,
	resultMaxLength: 600,
	maxEntryBytes: 0,
	maxEntries: 500,
	telemetryMaxCount: RECORD_LIMITS.telemetryMaxCount,
	rawMaxCount: RECORD_LIMITS.rawMaxCount,
	rawMaxBytes: RECORD_LIMITS.rawMaxBytes,
	harnessId: undefined,
	model: undefined,
	runId: undefined,
});

/***
 * MARK: excerptText
 * @description Bounds a text block to `maxLength` characters, appending an
 *   ellipsis when the text was cut. Storage caps only — display lines
 *   summarize through the shared toolLogFormat grammar instead.
 ***/
function excerptText(text, maxLength) {
	if (!maxLength || maxLength <= 0 || text.length <= maxLength) return text;
	return `${text.slice(0, maxLength)}…`;
}

/***
 * MARK: extractToolResultText
 * @description Flattens a tool_finished result payload into plain text, using
 *   the same shapes the engine has always read: plain string, `{content}`
 *   string, `{content: [{text}]}` array, or a JSON fallback. Redacted on the
 *   way out: the flattened text is appended to the already-stored [TOOL]
 *   entry (`meta.output`) AFTER its record passed the creation redactor, so
 *   an unredacted extract would leak secrets into the store.
 ***/
function extractToolResultText(event) {
	const flatten = () => {
		if (typeof event.result === "string") return event.result;
		if (typeof event.result?.content === "string") return event.result.content;
		if (Array.isArray(event.result?.content)) {
			return event.result.content
				.map((c) => (typeof c === "string" ? c : c?.text || ""))
				.join("");
		}
		if (event.result) {
			try {
				return JSON.stringify(event.result);
			} catch {
				return String(event.result);
			}
		}
		return "";
	};
	return redactSecretsText(flatten());
}

/***
 * MARK: readToolPartial
 * @description Reads the streamed partial output of a tool_updated event,
 *   redacted: partials accumulate on the stored [TOOL] entry after its
 *   record passed the creation redactor.
 ***/
function readToolPartial(event) {
	if (typeof event.partialResult === "string")
		return redactSecretsText(event.partialResult);
	if (typeof event.delta === "string") return redactSecretsText(event.delta);
	return "";
}

/***
 * MARK: createLogProcessor
 * @description Creates the unified event→record processor for one agent
 *   stage run. Pure: no harness imports, no I/O — only the normalized
 *   agent-event vocabulary in, canonical records out.
 * @param {Object} [options] - See DEFAULT_PROCESSOR_OPTIONS.
 * @returns {Object} Processor with handleEvent/system/entries/snapshot helpers.
 ***/
export function createLogProcessor(options = {}) {
	const merged = { ...DEFAULT_PROCESSOR_OPTIONS, ...options };
	const hideThinking = merged.hideThinking !== false;
	const toolArgsMaxLength =
		merged.toolArgsMaxLength ?? DEFAULT_PROCESSOR_OPTIONS.toolArgsMaxLength;
	const resultMaxLength =
		merged.resultMaxLength ?? DEFAULT_PROCESSOR_OPTIONS.resultMaxLength;
	const maxEntryBytes = merged.maxEntryBytes || 0;
	const maxEntries =
		merged.maxEntries > 0 ? merged.maxEntries : DEFAULT_PROCESSOR_OPTIONS.maxEntries;
	const telemetryMaxCount =
		merged.telemetryMaxCount > 0
			? merged.telemetryMaxCount
			: DEFAULT_PROCESSOR_OPTIONS.telemetryMaxCount;
	const rawMaxCount =
		merged.rawMaxCount > 0 ? merged.rawMaxCount : DEFAULT_PROCESSOR_OPTIONS.rawMaxCount;
	const rawMaxBytes =
		merged.rawMaxBytes > 0 ? merged.rawMaxBytes : DEFAULT_PROCESSOR_OPTIONS.rawMaxBytes;
	const contextFields = {};
	if (typeof merged.harnessId === "string" && merged.harnessId) {
		contextFields.harnessId = merged.harnessId;
	}
	if (merged.model !== undefined && merged.model !== null) {
		contextFields.model = merged.model;
	}
	if (typeof merged.runId === "string" && merged.runId) {
		contextFields.runId = merged.runId;
	}

	/** Monotonic entry ids: never Date.now() so same-millisecond events cannot collide. */
	let nextEntryId = 1;
	/** Monotonic record sequence numbers for the canonical record. */
	let nextSeq = 1;
	/** Semantic block counter: one blockId per text/thinking/tool block. */
	let nextBlock = 1;
	/** 1-based turn counter (run_started … run_finished). */
	let turnIndex = 0;
	/** All retained entries in creation order. */
	const entries = [];
	/** Open assistant text block for the streaming message. */
	let textBuffer = "";
	/** Open thinking block for the streaming message. */
	let thinkingBuffer = "";
	/** Role of the message currently streaming (assistant …). */
	let messageRole = null;
	/** The tool entry currently accumulating output (tool_started … tool_finished). */
	let openToolEntry = null;
	/** Wall-clock start per open tool entry (WeakMap so parallel calls keep
	 *  their own start; never stored on the record itself). */
	const toolStartMs = new WeakMap();
	/** Steps faster than this render no measured timing suffix: same-tick
	 *  unit pairs stay byte-identical while real tool calls (≥100ms) show
	 *  how long each step took. Explicit event timings always render. */
	const MEASURED_TIMING_FLOOR_MS = 100;

	const firstFiniteMs = (...values) => {
		for (const value of values) {
			if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
				return value;
			}
		}
		return null;
	};

	const explicitDurationMs = (event = {}) =>
		firstFiniteMs(
			event.durationMs,
			event.duration_ms,
			typeof event.duration_seconds === "number" ? event.duration_seconds * 1000 : null,
			typeof event.durationSeconds === "number" ? event.durationSeconds * 1000 : null,
		);

	const formatDurationMs = (ms) =>
		ms >= 1000 ? `${(ms / 1000).toFixed(1)}s` : `${Math.round(ms)}ms`;
	/** Marker entry tracking evicted entries, so repeated eviction updates one line. */
	let evictionMarker = null;
	let evictedCount = 0;
	/** Marker entry tracking raw-lane evictions (stays on the raw feed). */
	let rawEvictionMarker = null;
	let rawEvictedCount = 0;
	/** Telemetry records retained (reserved budget inside maxEntries). */
	let telemetryCount = 0;
	/** Last emitted usage payload JSON — suppresses double telemetry when the
	 *  same usage object arrives both as usage_updated and on run_finished. */
	let lastUsageJson = null;

	const capText = (text) =>
		maxEntryBytes > 0 ? excerptText(text, maxEntryBytes) : text;

	const appendRecord = (partial) => {
		const record = makeLogRecord({
			...contextFields,
			turn: turnIndex || 1,
			...partial,
			id: nextEntryId++,
			seq: nextSeq++,
			ts: new Date().toISOString(),
		});
		// ANSI escapes never reach stored text (they would leak into HTML
		// rendering); the verbatim wire bytes stay available in evidence.
		// Secrets/PII are redacted BEFORE the length cap so a truncated
		// secret fragment can never survive beside a cut marker. Clean text
		// passes through byte-identical.
		if (typeof record.text === "string" && record.text) {
			record.text = capText(redactSecretsText(stripAnsiText(record.text)));
		}
		// Structured payloads redact by position (secret-shaped keys) and by
		// shape (tokens, emails, paths inside free text). Numbers/booleans
		// pass through untouched, so usage counts and exit codes survive.
		if (record.meta && typeof record.meta === "object") {
			record.meta = redactDeepStrings(record.meta);
		}
		if (record.tool && typeof record.tool === "object") {
			record.tool = redactDeepStrings(record.tool);
		}
		if (record.usage && typeof record.usage === "object") {
			record.usage = redactDeepStrings(record.usage);
		}
		if (record.evidence && typeof record.evidence === "object") {
			record.evidence = redactDeepStrings(record.evidence);
		}
		entries.push(record);
		evictOverflow();
		return record;
	};

	const appendEntry = ({ kind, feeds: entryFeeds, text, meta, ...rest }) => {
		return appendRecord({
			kind,
			feeds: entryFeeds,

				"tests/run-parallel.test.mjs",
				"tests/repeat-tests.test.mjs",
				"tests/deprecation-gate.test.mjs",
				"tests/free-port.test.mjs",
				"tests/canary-preflight.test.mjs",
				"tests/deploy-gates.test.mjs",
				"tests/run-supervised.test.mjs",
				"tests/run-tests.test.mjs",
				"tests/dev.test.mjs",
				"tests/deploy-reexec.test.mjs",
				"tests/setup.test.mjs",
				"tests/storage-sanity.test.mjs",
				"tests/remediate-no-verdict-rejections.test.mjs",
				"tests/entry-platform.test.mjs",
				"tests/check-one-function-per-file.test.mjs",
				"tests/check-jsdoc-example.test.mjs",
				"tests/check-duplicate-settings.test.mjs",
				"tests/check-component-compat.test.mjs",
				"tests/detect-changed-components.test.mjs",
				"tests/publish.test.mjs",
				"tests/redeploy.test.mjs",
			],
			lowPriority: true,
		},
	);
	if (hasDocker) {
